      (rows.length ? rows.map(function (r) {
        return '<tr class="click" data-act="openap" data-v="' + r.b.id + '" tabindex="0"><td class="nw mono">' + esc(r.b.no) + '</td><td class="name">' + esc(r.s.name) + (r.s.critical ? ' <span class="badge b-blue plain">' + th('Critical') + '</span>' : '') + '</td><td class="nw">' + dt(r.b.due) + '</td><td>' + statusBadge(r.st, r.late) + '</td><td class="nw">' + (r.pay ? dt(r.pay) + (r.b.planned ? '<small>' + th('planned by you') + '</small>' : '') : '<span class="muted">' + th('not in forecast') + '</span>') + '</td><td class="num">' + eur2(r.b.amount) + '</td></tr>';
      }).join('') : '<tr><td colspan="6" class="empty">' + th('No bills match.') + '</td></tr>') + '</tbody></table></div></section>';
