    var rec = db.recurring.slice().sort(function (a, b) { return (E.CAT[a.cat].kind === 'in' ? 0 : 1) - (E.CAT[b.cat].kind === 'in' ? 0 : 1) || b.amount - a.amount; });
    h += '<section class="card"><div class="card-h"><div><span class="label">' + esc(plural(rec.length, 'rule', 'rules')) + '</span><h2>' + th('Recurring') + '</h2></div></div><div class="tw"><table class="t"><thead><tr><th>' + th('Item') + '</th><th>' + th('Category') + '</th><th>' + th('When') + '</th><th>' + th('Next') + '</th><th class="num">' + th('In 13 weeks') + '</th><th class="num">' + th('Amount') + '</th></tr></thead><tbody>' +
      rec.map(function (r) {
        var occ = E.occurrences(r, TODAY, end), tot = f.items.filter(function (it) { return it.src === 'rec' && it.id === r.id; }).reduce(function (s, it) { return s + it.amount; }, 0), k = E.CAT[r.cat].kind;
        return '<tr class="click' + (r.off ? ' muted' : '') + '" data-act="recedit" data-v="' + r.id + '" tabindex="0"><td class="name">' + esc(lx(r.name)) + (r.off ? ' <span class="tag">' + th('paused') + '</span>' : '') + (r.note ? '<small>' + esc(lx(r.note)) + '</small>' : '') + '</td><td><span class="badge ' + (k === 'in' ? 'b-good' : 'b-clay') + '">' + esc(catName(r.cat)) + '</span></td><td class="nw">' + esc(whenText(r)) + (r.end ? '<small>' + th('until {date}', { date: dt(r.end) }) + '</small>' : '') + (r.start > TODAY ? '<small>' + th('from {date}', { date: dt(r.start) }) + '</small>' : '') + '</td><td class="nw">' + (occ[0] && !r.off ? dt(occ[0]) : '—') + '</td><td class="num ' + (k === 'in' ? 'pos' : 'neg') + '">' + (tot ? (k === 'in' ? '+' : '−') + eur(tot) : '–') + '</td><td class="num">' + eur(r.amount) + '</td></tr>';
      }).join('') + '</tbody></table></div></section>';
    var pl = db.planned.slice().sort(function (a, b) { return a.date < b.date ? -1 : 1; });
    h += '<section class="card" style="margin-top:14px"><div class="card-h"><div><span class="label">' + esc(plural(pl.length, 'item', 'items')) + '</span><h2>' + th('One-offs and pipeline deals') + '</h2></div></div><div class="tw"><table class="t"><thead><tr><th>' + th('Item') + '</th><th>' + th('Category') + '</th><th>' + th('Date') + '</th><th class="num">' + th('Likely') + '</th><th class="num">' + th('Counted') + '</th><th class="num">' + th('Amount') + '</th></tr></thead><tbody>' +
      pl.map(function (p) {
        var k = E.CAT[p.cat].kind, it = f.items.filter(function (x) { return x.src === 'plan' && x.id === p.id; })[0];
        return '<tr class="click' + (p.done ? ' muted' : '') + '" data-act="planedit" data-v="' + p.id + '" tabindex="0"><td class="name">' + esc(lx(p.name)) + (p.done ? ' <span class="tag">' + th('done') + '</span>' : '') + (p.note ? '<small>' + esc(lx(p.note)) + '</small>' : '') + '</td><td><span class="badge ' + (k === 'in' ? 'b-good' : 'b-clay') + '">' + esc(catName(p.cat)) + '</span></td><td class="nw">' + dt(p.date) + (p.date > f.end ? '<small>' + th('after the forecast') + '</small>' : '') + '</td><td class="num">' + (k === 'in' ? p.prob + ' %' : '–') + '</td><td class="num ' + (k === 'in' ? 'pos' : 'neg') + '">' + (it ? (k === 'in' ? '+' : '−') + eur(it.amount) : '–') + '</td><td class="num">' + eur(p.amount) + '</td></tr>';
      }).join('') + '</tbody></table></div></section>';
