      LANG_OPTS.map(function (o) { return '<button type="button" data-act="uilang" data-v="' + o[0] + '" lang="' + o[0] + '" aria-pressed="' + (LANG === o[0]) + '">' + o[1] + '</button>'; }).join('') + '</div></div></section>';
    h += '<div id="syncPanel" style="margin:0 0 14px"></div>';
