        r.items.slice(0, 8).map(function (it) { return '<tr><td class="mono">' + it.line + '</td><td class="mono nw">' + esc(it.no) + '</td><td class="name">' + esc(it.party) + (it.vatId ? '<small>' + esc(it.vatId) + '</small>' : '') + '</td><td class="nw">' + dt(it.issued) + '</td><td class="nw">' + dt(it.due) + '</td><td class="num">' + eur2(it.amount) + '</td><td class="small-cell">' + esc(stateOf[it.line] || '') + '</td></tr>'; }).join('') +
        (r.items.length > 8 ? '<tr><td colspan="7" class="muted">' + th('… and {n} more', { n: r.items.length - 8 }) + '</td></tr>' : '') + '</tbody></table></div>';
      if (pl.doubtful) h += '<p class="hint">' + th('Over {days} days overdue: {invoices}. Imported, but left out of the forecast until you set an expected date.', { days: E.DOUBTFUL_DAYS, invoices: esc(plural(pl.doubtful, 'invoice', 'invoices')) }) + '</p>';
      if (pl.gone.length) h += '<label class="check"><input type="checkbox" id="impComplete"' + (imp.complete ? ' checked' : '') + '> ' + th(ar ? 'This file is the complete list of open invoices: treat the {items} that are not in it ({amount}) as paid' : 'This file is the complete list of open bills: treat the {items} that are not in it ({amount}) as paid', { items: esc(plural(pl.gone.length, ar ? 'open invoice' : 'open bill', ar ? 'open invoices' : 'open bills')), amount: eur2(pl.gone.reduce(function (s, x) { return s + x.amount; }, 0)) }) + '</label>';
