      download('payables-' + TODAY + '.csv', csv([[tx('Bill number'), tx('Supplier'), tx('Issue date'), tx('Due date'), tx('Status'), tx('Pay on'), tx('Amount')]].concat(db.ap.filter(function (b) { return !b.paid; }).map(function (b) { var st = E.apStatus(b, TODAY); return [b.no, (SUPP[b.supplierId] || {}).name, b.issued, b.due, AP_STATUS[st] ? tx(AP_STATUS[st]) : st, pay[b.id] || '', num2(b.amount)]; }))));
