    backup: function () { downloadBackup(); },
    restore: function () { var p = $('restorePick'); p.value = ''; p.click(); },
    startown: function () {
      var ds = demoState();
      if (ds === 'own') { toast(tx('This app already holds your own data.')); return; }
      var typed = ds !== 'pristine';
      modal(tx('Start your own forecast?'), '<p>' + th('This replaces the demo with an empty forecast for your company: one bank account, no invoices, bills or recurring items yet.') + ' ' + th(CLOUD_WARN) + '</p>' +
        fld('ownName', 'Company name', '<input class="in" id="ownName" maxlength="80" autocomplete="organization">') +
        '<p class="sub">' + th('Then: set the balances (or import a bank statement) here, import open invoices and bills on Receivables and Payables, or fill them from Billing and Invoices, and add payroll, taxes and rent under Recurring & planned.') + '</p>' +
        (typed ? fld('resetWord', 'The demo has your changes. Type RESET to replace it', '<input class="in" id="resetWord" autocomplete="off" autocapitalize="characters" spellcheck="false">') : ''), tx('Start empty'), function () {
        var name = String($('ownName').value || '').trim();
        if (!name) { modalError(tx('Enter your company name.')); return; }
        if (typed && String(($('resetWord') || {}).value || '').trim().toUpperCase() !== 'RESET') { modalError(tx('Type RESET to confirm.')); return; }
        clearTimeout(saveTimer);
        db = { version: X.VERSION, own: true, generatedFor: '', company: { name: name, what: '', currency: 'EUR' }, settings: { minCash: 0, creditLine: 0, owner: '' },
          accounts: [{ id: 'a1', name: tx('Main current account'), bank: '', balance: 0 }], customers: [], suppliers: [], ar: [], ap: [], recurring: [], planned: [], history: [], log: [Object.assign({ at: TODAY }, msg('Started your own forecast'))] };
        reindex(); idbOK = true; demoRef = null; saveTimer = 1; flush(); closeLayer(); location.hash = '#/settings'; render(); toast(tx('Your own forecast is ready: start with the bank balances'));
      }, '<button type="button" class="btn" data-act="backup">' + ic('dl') + th('Download backup first') + '</button>');
    },
